using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace WinUp {
    partial class MainForm {
        NotesWindow notesWindow; bool notesLocking;
        void BuildCodeImagesTab(){var page=new TabPage("QR / штрихкод");var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true};var button=new Button{Text="Создать QR / штрихкод",AutoSize=true};button.Click+=(s,e)=>ShowCodeImage();bar.Controls.Add(button);page.Controls.Add(bar);ArrangeActions(page,new[]{bar},new ActionGroup("Создание",Actions(bar,"Создать QR / штрихкод")));tabs.TabPages.Add(page);}
        readonly ListBox noteList=new ListBox{Dock=DockStyle.Fill,DisplayMember="Title"};
        void BuildNotesTab(){var page=new TabPage("Заметки");var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true};foreach(string text in new[]{"Добавить заметку","Открыть заметку","Отдельное окно","QR / штрихкод"}){var button=new Button{Text=text,AutoSize=true};string action=text;button.Click+=(s,e)=>{if(action=="QR / штрихкод"){ShowCodeImage();return;}OpenNotes(action=="Добавить заметку"?null:(noteList.SelectedItem as SecureNoteInfo)==null?null:((SecureNoteInfo)noteList.SelectedItem).Id,action=="Добавить заметку");};bar.Controls.Add(button);}page.Controls.Add(noteList);page.Controls.Add(bar);ArrangeActions(page,new[]{bar},new ActionGroup("Заметки",Actions(bar,"Добавить заметку","Открыть заметку","Отдельное окно")),new ActionGroup("Инструменты",Actions(bar,"QR / штрихкод")));noteList.DoubleClick+=(s,e)=>OpenNotes((noteList.SelectedItem as SecureNoteInfo)==null?null:((SecureNoteInfo)noteList.SelectedItem).Id,false);tabs.TabPages.Add(page);}
        void RefreshNotes(){if(noteList==null)return;noteList.Items.Clear();if(vault!=null)foreach(var item in vault.NoteItems())noteList.Items.Add(item);}
        void OpenNotes(string id=null,bool create=false){if(vault==null){ShowFromTray();Unlock();if(vault==null)return;}if(notesWindow==null||notesWindow.IsDisposed){notesWindow=new NotesWindow(vault,()=>vault,SaveVaultOf,RefreshNotes,()=>notesLocking);notesWindow.Show();}else{notesWindow.WindowState=FormWindowState.Normal;notesWindow.Activate();}if(create)notesWindow.NewNote();else if(!string.IsNullOrEmpty(id))notesWindow.SelectNote(id);}
        void ShowCodeImage(){using(var dialog=new CodeImageDialog())dialog.ShowDialog(this);}
        void ShowRecoveryCodes(){var entry=SelectedEntry();if(vault==null||entry==null)throw new IOException("Выберите аккаунт в открытой базе.");var active=vault;using(var dialog=new RecoveryCodesView(entry)){if(dialog.ShowDialog(this)==DialogResult.OK&&vault==active){var codes=dialog.Value;try{entry.RecoveryCodes=codes;if(!SaveVaultOf(active))LockVault();}finally{Secure.Wipe(codes);}}}}
    }
    sealed class NotesWindow:Form,ILockableDialog {
        readonly KdbxStore store;readonly Func<KdbxStore> current;readonly Func<KdbxStore,bool> save;readonly Action changed;readonly Func<bool> locking;
        readonly ListBox list=new ListBox{Dock=DockStyle.Fill,DisplayMember="Title"};readonly TextBox search=new TextBox{Dock=DockStyle.Top};readonly TextBox title=new TextBox{Dock=DockStyle.Top,MaxLength=160};readonly TextBox text=new TextBox{Dock=DockStyle.Fill,Multiline=true,AcceptsTab=true,AcceptsReturn=true,ScrollBars=ScrollBars.Vertical,MaxLength=262144};readonly Label status=new Label{Dock=DockStyle.Bottom,Height=28};readonly Timer timer=new Timer{Interval=1200};string selected;bool loading,dirty,saving;
        internal NotesWindow(KdbxStore store,Func<KdbxStore> current,Func<KdbxStore,bool> save,Action changed,Func<bool> locking){this.locking=locking;this.store=store;this.current=current;this.save=save;this.changed=changed;Text="WinUp — заметки";Font=new Font("Segoe UI",10);Icon=AppIcons.Open;Size=new Size(880,640);MinimumSize=new Size(620,430);StartPosition=FormStartPosition.CenterScreen;var left=new Panel{Dock=DockStyle.Left,Width=240,Padding=new Padding(8)};left.Controls.Add(list);left.Controls.Add(search);left.Controls.Add(new Label{Text="Поиск заметок",Dock=DockStyle.Top,Height=24});var editor=new Panel{Dock=DockStyle.Fill,Padding=new Padding(10)};editor.Controls.Add(text);editor.Controls.Add(title);editor.Controls.Add(new Label{Text="Заголовок",Dock=DockStyle.Top,Height=24});editor.Controls.Add(status);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true};foreach(string name in new[]{"Новая","Сохранить","Удалить","QR / штрихкод"}){var b=new Button{Text=name,AutoSize=true};string action=name;b.Click+=(s,e)=>{if(action=="Новая")NewNote();else if(action=="Сохранить")Commit();else if(action=="Удалить")Remove();else using(var d=new CodeImageDialog())d.ShowDialog(this);};bar.Controls.Add(b);}Controls.Add(editor);Controls.Add(left);Controls.Add(bar);search.AccessibleName="Поиск заметок по заголовку";title.AccessibleName="Заголовок заметки";text.AccessibleName="Текст заметки";title.TextChanged+=(s,e)=>Edited();text.TextChanged+=(s,e)=>Edited();search.TextChanged+=(s,e)=>{if(Commit())Reload();};list.SelectedIndexChanged+=(s,e)=>{if(!loading&&list.SelectedItem is SecureNoteInfo)SelectNote(((SecureNoteInfo)list.SelectedItem).Id);};timer.Tick+=(s,e)=>{timer.Stop();Commit();};FormClosing+=(s,e)=>{timer.Stop();if(!Commit()&&current()==store&&!locking())e.Cancel=true;};FormClosed+=(s,e)=>{loading=true;timer.Dispose();text.Clear();title.Clear();};KeyPreview=true;KeyDown+=(s,e)=>{if(e.Control&&e.KeyCode==Keys.S){e.SuppressKeyPress=true;Commit();}};Reload();if(list.Items.Count>0)SelectNote(((SecureNoteInfo)list.Items[0]).Id);Appearance.Apply(this);}
        void Edited(){if(loading)return;dirty=true;status.Text="Изменения сохраняются…";timer.Stop();timer.Start();}
        bool Commit(){if(!dirty||saving)return true;if(current()!=store){loading=true;text.Clear();title.Clear();dirty=false;timer.Stop();return false;}saving=true;try{selected=store.PutNote(selected,string.IsNullOrWhiteSpace(title.Text)?"Без названия":title.Text,text.Text);if(!save(store)){status.Text="Не удалось сохранить. Базу нужно открыть заново.";return false;}dirty=false;status.Text="Сохранено · "+DateTime.Now.ToString("HH:mm:ss");changed();Reload();return true;}catch(Exception ex){status.Text=ex.Message;return false;}finally{saving=false;}}
        void Reload(){loading=true;try{list.Items.Clear();foreach(var n in store.NoteItems().Where(n=>n.Title.IndexOf(search.Text,StringComparison.CurrentCultureIgnoreCase)>=0)){list.Items.Add(n);if(n.Id==selected)list.SelectedItem=n;}}finally{loading=false;}}
        internal void NewNote(){if(!Commit())return;selected=null;loading=true;title.Text="";text.Text="";loading=false;status.Text="Новая заметка · сохраняется при вводе";title.Focus();}
        internal void SelectNote(string id){if(id==selected)return;if(!Commit())return;selected=id;string body=store.ReadNote(id);try{loading=true;title.Text=store.NoteItems().First(n=>n.Id==id).Title;var handle=text.Handle;text.Text=body;status.Text="Сохранено";Reload();}finally{loading=false;Secure.Wipe(body);}}
        void Remove(){if(selected==null){NewNote();return;}if(MessageBox.Show(this,"Переместить заметку в корзину?","WinUp — заметки",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;timer.Stop();store.DeleteNote(selected);if(!save(store))return;dirty=false;selected=null;loading=true;text.Clear();title.Clear();loading=false;changed();Reload();}
    }
    sealed class RecoveryCodesView:Dlg,ILockableDialog {
        readonly ListBox list=new ListBox{Height=230,Width=420,Font=new Font("Consolas",12)};readonly Label status;public string Value{get{return string.Join("\n",list.Items.Cast<string>());}}
        public RecoveryCodesView(LoginEntry entry):base("Резервные коды — "+entry.Name){Note("Выберите код для копирования. Использованный код можно убрать из списка.");entry.UseRecoveryCodes(c=>{foreach(var code in (c??"").Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries))list.Items.Add(code);return 0;});Row("Коды:",list);status=Note(list.Items.Count==0?"Коды пока не сохранены.":"Сохранено кодов: "+list.Items.Count);var bar=new FlowLayoutPanel{AutoSize=true};foreach(var name in new[]{"Копировать код","Убрать использованный","Изменить список"}){var b=new Button{Text=name,AutoSize=true};string action=name;b.Click+=(s,e)=>{if(action=="Изменить список"){using(var d=new RecoveryCodesDialog(Value))if(d.ShowDialog(this)==DialogResult.OK){list.Items.Clear();foreach(var code in d.Value.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries))list.Items.Add(code);}}else if(list.SelectedIndex>=0){if(action=="Копировать код")SecureClip.Copy((string)list.SelectedItem);else list.Items.RemoveAt(list.SelectedIndex);}status.Text="Кодов: "+list.Items.Count;};bar.Controls.Add(b);}FullRow(bar);Buttons();Ok.Text="Сохранить и закрыть";}
        protected override void Dispose(bool disposing){if(disposing)list.Items.Clear();base.Dispose(disposing);}
    }
}
